module external_hermite
    implicit none
    public :: hermite

contains
    FUNCTION hermite(npt, func, ier) RESULT(fn_val)
        !! Author: Alan Miller
        !!
        !! Original Source: https://wp.csiro.au/alanmiller/hermite.f90
        !! Used with Alan Miller's permission
        !!
        !!       HERMITE INTEGRATION, I.E. EVALUATION OF THE INTEGRAL OF
        !!       exp(-x**2)*f(x) FROM -INFINITY TO +INFINITY
        !!
        !!       NPT     = INPUT, NO. OF POINTS AT WHICH f(x) IS TO BE EVALUATED.
        !!                 NPT MUST BE ONE OF 2, 4, 6, 8, 10, 12, 16, 20.
        !!       FUNC    = INPUT, NAME OF THE USER'S FUNCTION TO SUPPLY VALUES
        !!                 OF F(X).   THE FUNCTION MAY HAVE ANY NAME BUT ONLY THE
        !!                 ONE ARGUMENT, X.
        !!       IER     = OUTPUT, ERROR INDICATOR
        !!                   = 0 NO ERROR DETECTED
        !!                   = 1 ILLEGAL VALUE OF NPT
        !!
        !!       LATEST REVISION - 5 December 1999
        ! ************************************************************************

        IMPLICIT NONE
        INTEGER, PARAMETER :: dp = SELECTED_REAL_KIND(12, 60)

        INTEGER, INTENT(IN)  :: npt
        INTEGER, INTENT(OUT) :: ier
        REAL (dp)            :: fn_val

        INTERFACE
            FUNCTION func(x) RESULT(fn_val)
                IMPLICIT NONE
                INTEGER, PARAMETER    :: dp = SELECTED_REAL_KIND(12, 60)
                REAL (dp), INTENT(IN) :: x
                REAL (dp)             :: fn_val
            END FUNCTION func
        END INTERFACE

        !     Local variables

        REAL (dp) :: xpt(89) = (/ 0.707106781186548_dp, &
            0.524647623275290_dp, 1.650680123885785_dp, &
            0.436077411927617_dp, 1.335849074013697_dp, 2.350604973674492_dp, &
            0.381186990207322_dp, 1.157193712446780_dp, 1.981656756695843_dp, &
            2.930637420257244_dp, &
            0.342901327223705_dp, 1.036610829789514_dp, 1.756683649299882_dp, &
            2.532731674232790_dp, 3.436159118837738_dp, &
            0.314240376254359_dp, 0.947788391240164_dp, 1.597682635152605_dp, &
            2.279507080501060_dp, 3.020637025120890_dp, 3.889724897869782_dp, &
            0.27348104613815_dp,  0.82295144914466_dp, 1.38025853919888_dp, &
            1.95178799091625_dp,  2.54620215784748_dp, 3.17699916197996_dp, &
            3.86944790486012_dp,  4.68873893930582_dp, &
            0.2453407083009_dp,   0.7374737285454_dp, 1.2340762153953_dp, &
            1.7385377121166_dp,   2.2549740020893_dp, 2.7888060584281_dp, &
            3.3478545673832_dp,   3.9447640401156_dp, 4.6036824495507_dp, &
            5.3874808900112_dp, &
            0.11079587242243949_dp,0.3324146923422318_dp,0.554114823591617_dp,&
            0.7759507615401458_dp,0.9979774360981052_dp,1.220250391218953_dp,&
            1.4428259702159327_dp,1.6657615087415094_dp,1.8891155374270083_dp,&
            2.112947996371188_dp,2.3373204639068783_dp,2.562296402372608_dp,&
            2.7879414239819895_dp,3.0143235803311557_dp,3.241513679631013_dp,&
            3.4695856364185893_dp,3.698616859318492_dp,3.928688683427671_dp,&
            4.15988685513103_dp,4.392302078682684_dp,4.6260306357871555_dp,&
            4.86117509179121_dp,5.097845105089136_dp,5.33615836013836_dp,&
            5.5762416493299245_dp,5.818232135203517_dp,6.062278832614303_dp,&
            6.308544361112135_dp,6.557207031921539_dp,6.808463352858796_dp,&
            7.062531060248865_dp,7.319652822304535_dp,7.580100807857489_dp,&
            7.844182384460821_dp,8.112247311162792_dp,8.384696940416266_dp,&
            8.661996168134518_dp,8.944689217325475_dp,9.233420890219161_dp,&
            9.528965823390115_dp,9.832269807777969_dp,10.144509941292846_dp,&
            10.467185421342812_dp,10.802260753684715_dp,11.152404385585125_dp,&
            11.521415400787031_dp,11.915061943114166_dp,12.342964222859674_dp,&
            12.82379974948781_dp,13.406487338144911_dp/), &
            wt(89) = (/ 8.862269254528D-1, &
            8.049140900055D-1, 8.131283544725D-2, &
            7.246295952244D-1, 1.570673203229D-1, 4.530009905509D-3, &
            6.611470125582D-1, 2.078023258149D-1, 1.707798300741D-2, &
            1.996040722114D-4, &
            6.108626337353D-1, 2.401386110823D-1, 3.387439445548D-2, &
            1.343645746781D-3, 7.640432855233D-6, &
            5.701352362625D-1, 2.604923102642D-1, 5.160798561588D-2, &
            3.905390584629D-3, 8.573687043588D-5, 2.658551684356D-7, &
            5.079294790166D-1, 2.806474585285D-1, 8.381004139899D-2, &
            1.288031153551D-2, 9.322840086242D-4, 2.711860092538D-5, &
            2.320980844865D-7, 2.654807474011D-10, &
            4.622436696006D-1, 2.866755053628D-1, 1.090172060200D-1, &
            2.481052088746D-2, 3.243773342238D-3, 2.283386360163D-4, &
            7.802556478532D-6, 1.086069370769D-7, 4.399340992273D-10, &
            2.229393645534D-13, &
            0.21889262958743907_dp,0.19846285025418658_dp,0.16313003050278288_dp,0.12153798684410431_dp,&
            0.08205182739122438_dp,0.05017581267742869_dp,0.027779127385933536_dp,0.0139156652202318_dp,&
            0.006303000285608057_dp,0.0025792732600590914_dp,0.0009526921885486212_dp,0.00031729197104330017_dp,&
            9.517162778550938d-05,2.5676159384548985d-05,6.221524817777863d-06,1.3517971591103664d-06,&
            2.629097483753728d-07,4.568127508484932d-08,7.075857283889625d-09,9.74792125387158d-10,&
            1.1913006349290783d-10,1.2879038257315495d-11,1.2278785144101313d-12,1.0288749373509969d-13,&
            7.548896877915176d-15,4.829835321703059d-16,2.6824921647603564d-17,1.2868329211211485d-18,&
            5.302316183131867d-20,1.8649976751302644d-21,5.561026961659205d-23,1.3948415260687771d-24,&
            2.9173500726293086d-26,5.037791166213166d-28,7.101812226385044d-30,8.067434278709205d-32,&
            7.274572596887653d-34,5.116232604385216d-36,2.7487848843571495d-38,1.1004706827142353d-40,&
            3.185217877835948d-43,6.4207252053484285d-46,8.597563954825298d-49,7.191529463463198d-52,&
            3.459477936475526d-55,8.518883081761247d-59,9.019222303693468d-63,3.083028990003312d-67,&
            1.972860574879364d-72,5.908067865030892d-79 &
            /), zero = 0.0_dp, x
        INTEGER  :: npts(9) = (/ 2, 4, 6, 8, 10, 12, 16, 20, 100/), ipos, i, nby2

        !       CHECK FOR PERMISSIBLE VALUE OF NPT.

        fn_val = zero
        ipos = 1
        DO i = 1, 9
            IF(npts(i).EQ.npt) GO TO 20
            ipos = ipos + (npts(i) + 1)/2
        END DO
        ier = 1
        RETURN

        !       EVALUATE SUM OF WT(I) * FUNC(X(I))

20      nby2 = (npt + 1)/2
        DO i = 1, nby2
            x = xpt(ipos)
            fn_val = fn_val + wt(ipos) * (func(x) + func(-x))
            ipos = ipos + 1
        END DO
        ier = 0
        RETURN

    END FUNCTION hermite

end module external_hermite
